function getCaptchaInfo(){fetch("/CreateDntCaptchaParams",{method:"GET"}).then(n=>n.json()).then(n=>{$("#dntCaptchaImg").attr("src",n.dntCaptchaImgUrl),$("#DNTCaptchaText").attr("value",n.dntCaptchaTextValue),$("#DNTCaptchaToken").attr("value",n.dntCaptchaTokenValue),$("div.dntCaptcha").attr("id",n.dntCaptchaId)}).catch(()=>{$("#validationErrorMessage").html("خطا در تولید کپچا"),$("#validationErrorMessage").show()})}function doRefreshCaptcha(){getCaptchaInfo()}getCaptchaInfo();